package com.trombokendu.chronos.app;
import com.trombokendu.chronos.persistence.*;import com.trombokendu.chronos.ledger.*;import com.trombokendu.chronos.concurrency.*;import com.trombokendu.chronos.ui.*;import javax.swing.*;import java.sql.*;
public final class Main{private Main(){}public static void main(String[]args){ConnectionPool pool=new ConnectionPool("jdbc:sqlite:chronos.db",4);EventStore store=new EventStore();EventRepository repository=new EventRepository(pool);try(Connection c=pool.get()){new Migrator().migrate(c);for(StoredEvent e:repository.findAll())store.append(e.event());}catch(Exception e){pool.close();throw new IllegalStateException("Database startup failed",e);}EventBus bus=new EventBus();LedgerWriter writer=new LedgerWriter(store,bus,pool,repository);Runtime.getRuntime().addShutdownHook(new Thread(()->{writer.close();pool.close();}));SwingUtilities.invokeLater(()->new ChronosFrame(store,writer).setVisible(true));}}
